# ======================= HISTORIA ECONÓMICA DE COLOMBIA =======================
U={1:"Unidad 1 · Introducción e instituciones",2:"Unidad 2 · La Colonia (1500–1810)",3:"Unidad 3 · Siglo XIX (1810–1902)",4:"Unidad 4 · Siglo XX (1902–1974)",5:"Unidad 5 · De 1974 a hoy"}
guide(dict(slug="historia-economica-colombia",dir="hec",h1="Historia Económica de Colombia",nombre="Historia Económica de Colombia",cod="1503724",
  desc="Programa 1503724: nuevo institucionalismo y órdenes sociales, la economía colonial y las reformas borbónicas, la república naciente, el modelo liberal y la Regeneración, la economía cafetera, la crisis de 1929, la industrialización sustitutiva, la violencia, y la apertura y la Constitución de 1991.",
  colors=["#7b3f00","#f4e6d6","#d9a066","#371c00"],trunk="Tronco: de la Colonia al siglo XXI",
  intro="Resumen y guía de estudio del programa 1503724, siguiendo a Kalmanovitz (Nueva historia económica de Colombia; La economía de la Nueva Granada), Ocampo (Historia económica de Colombia) y el marco de North, Wallis y Weingast sobre órdenes sociales.",
  res="Instituciones y órdenes sociales, Colonia, reformas borbónicas, federalismo, café, industrialización, violencia, apertura y Constitución de 1991."),U,[
 ("instituciones",1,"Historia económica e instituciones","tarjetas",[
  ("Objeto y método",p("La historia económica explica el desempeño de largo plazo de una economía con teoría económica y evidencia cuantitativa (cliometría), atenta al contexto político y social. El <b>nuevo institucionalismo</b> (North) pone en el centro las instituciones: reglas formales e informales que definen derechos de propiedad, incentivos y costos de transacción.")),
  ("Órdenes sociales",p("North, Wallis y Weingast (Violencia y órdenes sociales, 2009) distinguen el <b>orden de acceso limitado</b> (estado natural), en el que una coalición de élites controla la violencia repartiéndose rentas y privilegios, y el <b>orden de acceso abierto</b>, con competencia política y económica e instituciones impersonales. La historia colombiana puede leerse como una transición lenta e incompleta entre ambos."))]),
 ("colonia",2,"La economía colonial","tiempo",[
  ("1500–1740",p("Tras la conquista, la población indígena se desplomó por las enfermedades, la guerra y el trabajo forzoso. La economía se organizó alrededor de la <b>minería de oro</b> (con mano de obra indígena y después esclavizada africana, en Antioquia, Chocó y Popayán), la encomienda y la mita, las haciendas y los resguardos indígenas. El monopolio comercial con España y los impuestos (quinto real, alcabala, diezmo) definían la relación con la metrópoli.")),
  ("El Virreinato y las reformas borbónicas (1740–1810)",p("La Nueva Granada fue Virreinato definitivamente desde 1739. Los Borbones buscaron aumentar el recaudo y el control: estancos de tabaco y aguardiente, más impuestos, una administración más centralizada y comercio libre entre puertos del imperio (1778). La presión fiscal provocó la <b>revolución de los Comuneros</b> (1781). La Expedición Botánica (Mutis) y la Ilustración alimentaron a la élite criolla que lideró la independencia."))]),
 ("siglo19",3,"El siglo XIX: república, federalismo y Regeneración","tiempo",[
  ("República naciente (1810–1850)",p("Las guerras de independencia destruyeron capital y finanzas públicas; la nueva república heredó deudas y un territorio fragmentado por la geografía, con regiones poco integradas. Se mantuvieron muchas instituciones coloniales (esclavitud hasta 1851, estancos).")),
  ("El modelo liberal (1850–1885)",p("Las reformas liberales de medio siglo abolieron la esclavitud (1851), los estancos y los resguardos, desamortizaron los bienes de la Iglesia (1861) y bajaron los aranceles. La Constitución de Rionegro (1863) creó los Estados Unidos de Colombia, federales. Hubo <b>ciclos exportadores</b> cortos (tabaco, quina, añil, algodón) y numerosas guerras civiles.")),
  ("La Regeneración (1886–1899)",p("Núñez y Caro impusieron la Constitución de 1886: centralismo, catolicismo oficial y proteccionismo. El Banco Nacional emitió papel moneda inconvertible que financió el déficit y generó inflación. El <b>café</b> se consolidó como principal exportación. La Guerra de los Mil Días (1899–1902) y la separación de Panamá (1903) cerraron el siglo."))]),
 ("siglo20",4,"Nación cafetera e industrialización (1902–1974)","tiempo",[
  ("Café y «prosperidad al debe» (1900–1928)",p("La colonización antioqueña expandió el café en pequeñas y medianas fincas; la Federación Nacional de Cafeteros se creó en 1927. La <b>Misión Kemmerer</b> (1923) creó el Banco de la República y la Contraloría. La indemnización de EE. UU. por Panamá y el crédito externo financiaron obras públicas.")),
  ("Crisis y cambio estructural (1929–1945)",p("La Gran Depresión cortó el crédito externo y bajó los precios del café. Colombia abandonó el patrón oro, devaluó y protegió la industria: la crisis impulsó la <b>industrialización</b> (textiles en Medellín: Coltejer, Fabricato). La Revolución en Marcha de López Pumarejo (1934–1938) reformó los impuestos y la tierra.")),
  ("Capitalismo moderno (1945–1974)",p("Industrialización por sustitución de importaciones, urbanización acelerada y la <b>Violencia</b> (1946–1958), que desplazó campesinos y concentró la tierra. El Frente Nacional (1958–1974) alternó el poder entre liberales y conservadores. Con Lleras Restrepo se creó un régimen cambiario de devaluación gradual (Decreto 444 de 1967) y se promovieron exportaciones menores. Hubo una segunda colonización agrícola hacia las fronteras."))]),
 ("reciente",5,"De la bonanza cafetera a la apertura","tiempo",[
  ("1974–1990",p("La bonanza cafetera de 1975–1979, el auge de la economía del narcotráfico, la crisis de la deuda latinoamericana de los ochenta (que Colombia sorteó mejor que sus vecinos), y el creciente conflicto armado.")),
  ("1990 en adelante",p("<b>Apertura económica</b> (Gaviria, 1990), Constitución de 1991 con Banco de la República independiente, descentralización fiscal, Ley 100 de 1993 (seguridad social). La crisis de 1999 (la primera recesión en décadas) llevó a la flotación cambiaria y a la inflación objetivo. Desde 2000: auge de las exportaciones de petróleo y carbón, regla fiscal (2011), acuerdo de paz con las FARC (2016)."))])],
 [(1,"Nuevo institucionalismo","Enfoque que explica el desempeño económico con las instituciones."),(1,"Orden de acceso limitado","Sociedad en que las élites controlan la violencia repartiéndose rentas."),(1,"Orden de acceso abierto","Sociedad con competencia política y económica abierta."),(2,"Encomienda","Asignación de indígenas a un español que cobraba tributo a cambio de protección y evangelización."),(2,"Mita","Trabajo forzoso por turnos de los indígenas."),(2,"Resguardo","Tierra colectiva de las comunidades indígenas."),(2,"Quinto real","Impuesto del 20 % sobre los metales preciosos."),(2,"Alcabala","Impuesto a las ventas."),(2,"Reformas borbónicas","Reformas fiscales y administrativas del siglo XVIII."),(2,"Comuneros","Revuelta de 1781 contra los nuevos impuestos."),(3,"Desamortización","Expropiación y venta de bienes de la Iglesia (1861)."),(3,"Constitución de Rionegro","Constitución federal de 1863."),(3,"Regeneración","Proyecto centralista y proteccionista de Núñez."),(4,"Misión Kemmerer","Asesoría de 1923 que creó el Banco de la República."),(4,"Federación Nacional de Cafeteros","Gremio cafetero creado en 1927."),(4,"Frente Nacional","Pacto bipartidista de 1958 a 1974."),(4,"Decreto 444 de 1967","Régimen cambiario y de control de capitales."),(5,"Apertura económica","Liberalización comercial iniciada en 1990.")],
 [(2,"La revolución de los Comuneros (1781) fue una reacción contra:",["La esclavitud","Los nuevos impuestos borbónicos","La independencia","El café"],1,"Presión fiscal."),(2,"La principal actividad exportadora colonial fue:",["Café","Minería de oro","Petróleo","Tabaco"],1,"Antioquia, Chocó y Popayán."),(3,"La esclavitud se abolió en Colombia en:",["1810","1851","1886","1903"],1,"Reforma liberal."),(3,"La Constitución de 1863 creó un Estado:",["Centralista","Federal","Monárquico","Confesional"],1,"Estados Unidos de Colombia."),(3,"La Regeneración se caracterizó por:",["Federalismo y librecambio","Centralismo y proteccionismo","Abolición de la esclavitud","Apertura"],1,"Constitución de 1886."),(4,"El Banco de la República se creó en:",["1886","1923","1951","1991"],1,"Misión Kemmerer."),(4,"La Gran Depresión en Colombia impulsó:",["La minería de oro","La industrialización","El federalismo","La apertura"],1,"Protección y devaluación."),(4,"El Frente Nacional fue:",["Una guerra civil","Un pacto de alternancia bipartidista","Un banco","Una reforma agraria"],1,"1958–1974."),(5,"La apertura económica comenzó en:",["1967","1990","1999","2011"],1,"Gobierno de Gaviria."),(5,"La crisis de 1999 llevó a:",["El patrón oro","La flotación cambiaria y la inflación objetivo","El Frente Nacional","La Regeneración"],1,"Cambio de régimen monetario.")],
 [(2,"Explique la estructura económica e institucional de la Nueva Granada y el efecto de las reformas borbónicas.",["Minería, haciendas, resguardos.","Trabajo forzoso.","Fiscalidad y monopolio.","Reformas y Comuneros."]),(3,"Compare el modelo liberal (1850–1885) con la Regeneración.",["Federalismo frente a centralismo.","Comercio y aranceles.","Iglesia y Estado.","Moneda y bancos."]),(4,"¿Por qué el café fue clave en la formación de la economía colombiana del siglo XX?",["Colonización y pequeña propiedad.","Divisas y acumulación.","Federación de Cafeteros.","Relación con la industria."])],
 [(2,"1538","Fundación de Santafé","Inicio del Nuevo Reino de Granada."),(2,"1739","Virreinato de la Nueva Granada","Restablecido definitivamente."),(2,"1781","Revolución de los Comuneros","Contra los impuestos borbónicos."),(3,"1810–1819","Independencia","Grito del 20 de julio y Boyacá."),(3,"1851","Abolición de la esclavitud","Reforma liberal."),(3,"1863","Constitución de Rionegro","Estados Unidos de Colombia."),(3,"1886","Constitución de 1886","Regeneración."),(3,"1899–1902","Guerra de los Mil Días","Última gran guerra civil."),(4,"1903","Separación de Panamá",""),(4,"1923","Misión Kemmerer","Banco de la República y Contraloría."),(4,"1927","Federación Nacional de Cafeteros",""),(4,"1948","El Bogotazo","Asesinato de Gaitán; la Violencia."),(4,"1958","Frente Nacional",""),(4,"1967","Decreto 444","Devaluación gradual."),(5,"1990","Apertura económica",""),(5,"1991","Constitución Política",""),(5,"1999","Crisis económica","Primera recesión en décadas."),(5,"2016","Acuerdo de paz con las FARC","")])

# ======================= EPISTEMOLOGÍA =======================
U={1:"Unidad 1 · Contexto histórico",2:"Unidad 2 · Fundamentos epistemológicos",3:"Unidad 3 · Filosofía de la ciencia y economía"}
guide(dict(slug="epistemologia",dir="epi",h1="Epistemología de las Ciencias Económicas",nombre="Epistemología de las Ciencias Económicas",cod="1503740",
  desc="Programa 1503740: el contexto histórico del nacimiento de la economía, conocimiento e interés, concepto, proposición y razonamiento, inducción y deducción, Popper, Kuhn, Lakatos y Feyerabend, Friedman y el realismo de los supuestos, McCloskey y la retórica.",
  colors=["#4a4e69","#e3e4ee","#9a8c98","#1f2130"],trunk="Tronco: las unidades del programa",
  intro="Resumen y guía de estudio del programa 1503740 sobre cómo conoce la economía: de la lógica del concepto a los grandes debates de la filosofía de la ciencia y su aplicación a la teoría económica.",
  res="Conocimiento y ciencia, concepto y razonamiento, inducción y deducción, Popper, Kuhn, Lakatos, Friedman, McCloskey y el estatus científico de la economía."),U,[
 ("contexto",1,"El contexto histórico del surgimiento de la ciencia económica","tarjetas",[
  ("Conocimiento e interés",p("El pensamiento científico es una práctica histórica y social. Habermas (Conocimiento e interés, 1968) distingue intereses técnicos (control), prácticos (comprensión) y emancipatorios que orientan el conocimiento. La paradoja de la ciencia moderna: promete autonomía y objetividad, pero se desarrolla ligada a intereses económicos y políticos.")),
  ("El nacimiento de la economía",p("La economía política surge en los siglos XVII y XVIII con el ascenso del comercio, el Estado moderno y la Ilustración: la confianza en que la sociedad, como la naturaleza newtoniana, obedece leyes. Smith concibe un orden que surge de las acciones individuales (la mano invisible). La geopolítica del conocimiento de la época situó a Europa como centro y al resto del mundo como periferia, tema que retoman los estudios decoloniales."))]),
 ("logica",2,"Concepto, proposición y razonamiento","tarjetas",[
  ("Elementos del conocimiento",p("Un <b>concepto</b> es una representación abstracta de una clase de objetos («costo de oportunidad»); se forma por <b>abstracción</b>, <b>definición</b> y <b>clasificación</b>. Una <b>proposición</b> afirma o niega algo y puede ser verdadera o falsa («la demanda tiene pendiente negativa»). Un <b>razonamiento</b> obtiene conclusiones a partir de premisas.")),
  ("Formas de razonamiento",ul("<b>Deducción</b>: de lo general a lo particular; si las premisas son verdaderas y la forma es válida, la conclusión es necesariamente verdadera. La teoría económica es en buena parte deductiva (modelos).","<b>Inducción</b>: de casos particulares a generalizaciones; la conclusión es solo probable. El problema de la inducción (Hume): ninguna cantidad de observaciones garantiza la siguiente.","<b>Abducción</b>: inferencia a la mejor explicación."),p("Dimensiones del conocimiento: empírico (sentido común), científico (sistemático, metódico, contrastable), filosófico."))]),
 ("filosofia",3,"Popper, Kuhn, Lakatos y Feyerabend","tiempo",[
  ("Del positivismo lógico a Popper",p("El <b>Círculo de Viena</b> (positivismo lógico) consideraba científicas solo las proposiciones verificables empíricamente. <b>Popper</b> (La lógica de la investigación científica, 1934) propuso el <b>falsacionismo</b>: una teoría es científica si puede ser refutada por la experiencia; la ciencia avanza por conjeturas y refutaciones. Criticó al marxismo y al psicoanálisis por inmunizarse contra la refutación.")),
  ("Kuhn, Lakatos, Feyerabend",ul("<b>Kuhn</b> (La estructura de las revoluciones científicas, 1962): la ciencia normal trabaja dentro de un <b>paradigma</b>; las anomalías acumuladas producen crisis y revoluciones científicas; los paradigmas son inconmensurables.","<b>Lakatos</b>: los <b>programas de investigación</b> tienen un núcleo duro protegido por un cinturón de hipótesis auxiliares; son progresivos si predicen hechos nuevos y degenerativos si solo se ajustan a posteriori.","<b>Feyerabend</b> (Contra el método, 1975): «todo vale»; no hay un método único que explique el progreso científico.")),
  ("La economía como ciencia",p("<b>Friedman</b> (La metodología de la economía positiva, 1953): el realismo de los supuestos no importa; una teoría se juzga por sus predicciones (instrumentalismo). Samuelson lo criticó. <b>Blaug</b> defendió el falsacionismo en economía y lamentó que se practique poco. <b>McCloskey</b> (La retórica de la economía, 1983): los economistas persuaden con metáforas, analogías y autoridad, no solo con pruebas formales. Hoy se discute el papel de los experimentos, la econometría y la causalidad (revolución de credibilidad)."))])],
 [(1,"Conocimiento e interés","Tesis de Habermas sobre los intereses que orientan el conocimiento."),(1,"Mano invisible","Metáfora de Smith sobre el orden que surge de acciones individuales."),(2,"Concepto","Representación abstracta de una clase de objetos."),(2,"Proposición","Enunciado que puede ser verdadero o falso."),(2,"Deducción","Razonamiento cuya conclusión se sigue necesariamente de las premisas."),(2,"Inducción","Generalización a partir de casos particulares."),(2,"Problema de la inducción","Imposibilidad de justificar lógicamente la inducción (Hume)."),(2,"Abducción","Inferencia a la mejor explicación."),(3,"Positivismo lógico","Criterio de verificación empírica del significado."),(3,"Falsacionismo","Una teoría es científica si puede ser refutada (Popper)."),(3,"Paradigma","Marco compartido de supuestos, problemas y métodos (Kuhn)."),(3,"Ciencia normal","Trabajo dentro de un paradigma aceptado."),(3,"Programa de investigación","Núcleo duro con cinturón protector (Lakatos)."),(3,"Instrumentalismo","Las teorías se juzgan por sus predicciones (Friedman)."),(3,"Retórica de la economía","Los economistas persuaden con recursos retóricos (McCloskey).")],
 [(2,"«Todos los cisnes observados son blancos, luego todos los cisnes son blancos» es:",["Deducción","Inducción","Abducción","Falacia formal"],1,"Generalización desde casos."),(2,"Un razonamiento deductivo válido con premisas verdaderas tiene conclusión:",["Probable","Necesariamente verdadera","Falsa","Indeterminada"],1,"Propiedad de la deducción."),(3,"Para Popper, una teoría es científica si:",["Ha sido verificada","Puede ser refutada","Es aceptada por la comunidad","Usa matemáticas"],1,"Falsabilidad."),(3,"El concepto de paradigma es de:",["Popper","Kuhn","Lakatos","Friedman"],1,"1962."),(3,"Para Lakatos, un programa es degenerativo si:",["Predice hechos nuevos","Solo se ajusta a posteriori a las anomalías","Es matemático","Tiene núcleo duro"],1,"No anticipa hechos."),(3,"«Todo vale» es una tesis de:",["Kuhn","Feyerabend","Popper","Blaug"],1,"Contra el método."),(3,"Friedman sostiene que los supuestos de una teoría:",["Deben ser realistas","No importan si la teoría predice bien","Deben ser verificados","Son falsos siempre"],1,"Instrumentalismo."),(3,"McCloskey destacó el papel en economía de:",["La falsación","La retórica","Los experimentos","La inducción"],1,"Metáforas y persuasión."),(1,"Habermas relaciona el conocimiento con:",["La lógica formal","Intereses técnicos, prácticos y emancipatorios","La inducción","La retórica"],1,"Conocimiento e interés."),(3,"El Círculo de Viena defendía el criterio de:",["Falsación","Verificación","Inconmensurabilidad","Retórica"],1,"Positivismo lógico.")],
 [(3,"¿Es la economía una ciencia? Discuta desde Popper, Kuhn y Lakatos.",["Criterio de demarcación.","Paradigmas en economía (keynesiano, neoclásico).","Programas progresivos o degenerativos.","Posición propia."]),(3,"Evalúe la tesis de Friedman sobre el realismo de los supuestos con un ejemplo.",["Instrumentalismo.","Ejemplo (competencia perfecta, racionalidad).","Críticas.","Conclusión."]),(2,"Explique la diferencia entre deducción e inducción en la investigación económica.",["Modelos teóricos.","Econometría.","Problema de la inducción.","Complementariedad."])],
 [(1,"1776","Smith, La riqueza de las naciones",""),(2,"1739","Hume, Tratado de la naturaleza humana","Problema de la inducción."),(3,"1934","Popper, La lógica de la investigación científica","Falsacionismo."),(3,"1953","Friedman, La metodología de la economía positiva",""),(3,"1962","Kuhn, La estructura de las revoluciones científicas",""),(1,"1968","Habermas, Conocimiento e interés",""),(3,"1970","Lakatos, programas de investigación",""),(3,"1975","Feyerabend, Contra el método",""),(3,"1980","Blaug, La metodología de la economía",""),(3,"1983","McCloskey, La retórica de la economía","")])

