 [(1,"La crisis de 1999 en Colombia estuvo asociada a:",["El auge del café","El colapso del crédito hipotecario y un ajuste externo","La pandemia","La independencia"],1,"Primera recesión en décadas."),(2,"Desde 1999 el régimen cambiario colombiano es de:",["Tipo de cambio fijo","Flotación con intervenciones ocasionales","Caja de convertibilidad","Dolarización"],1,"Tras abandonar la banda."),(2,"Cuando cae el precio del petróleo, el peso colombiano tiende a:",["Apreciarse","Depreciarse","No cambiar","Desaparecer"],1,"Menos divisas."),(3,"La regla fiscal colombiana se creó con la Ley:",["100 de 1993","1473 de 2011","617 de 2000","1819 de 2016"],1,"Reformada en 2021."),(3,"La meta de inflación del Banco de la República es:",["1 %","3 %","5 %","10 %"],1,"Con un rango de ± 1 punto."),(4,"La informalidad laboral en Colombia es aproximadamente:",["10 %","Cerca de la mitad de los ocupados","90 %","Inexistente"],1,"Según el DANE."),(4,"Una medida que redujo costos laborales no salariales fue:",["La Ley 100","La reforma tributaria de 2012","La Constitución de 1991","El Decreto 444"],1,"Exoneración de aportes."),(4,"El Gini del ingreso en Colombia está alrededor de:",["0,2","0,5","0,8","1"],1,"Entre los más altos de la región."),(1,"En 2020 el PIB de Colombia cayó cerca de:",["1 %","7 %","20 %","No cayó"],1,"Pandemia."),(2,"Las exportaciones colombianas se concentran en:",["Manufacturas de alta tecnología","Bienes minero-energéticos y agrícolas","Servicios financieros","Automóviles"],1,"Petróleo, carbón, café, flores, oro.")],
